/* The views' resource, icon and stylesheets, installed once per display (szfriends_gtk_internal.h).
 *
 * Nothing here runs at launch: the first Friends button asks for it. Both stylesheets follow libadwaita's dark state
 * through GtkCssProvider:prefers-color-scheme, which is what makes `@media (prefers-color-scheme: dark)` apply; GTK
 * does not read the system setting for a provider of its own. */

#include "gtk/szfriends_gtk_internal.h"

#include <adwaita.h>

/* Generated by glib-compile-resources --manual-register --c-name szfriends_gtk: registered on first use rather than
 * by a constructor, which a static library would drop anyway when nothing references its object. */
GResource *szfriends_gtk_get_resource(void);
void szfriends_gtk_register_resource(void);

GResource *szfriends_gtk_resource(void) {
    static gsize registered;
    if (g_once_init_enter(&registered)) {
        szfriends_gtk_register_resource();
        g_once_init_leave(&registered, 1);
    }
    return szfriends_gtk_get_resource();
}

static gboolean dark_to_scheme(GBinding *binding, const GValue *from, GValue *to, gpointer data) {
    (void)binding, (void)data;
    g_value_set_enum(to, g_value_get_boolean(from) ? GTK_INTERFACE_COLOR_SCHEME_DARK
                                                   : GTK_INTERFACE_COLOR_SCHEME_LIGHT);
    return TRUE;
}

static void log_css_error(GtkCssProvider *provider, GtkCssSection *section, GError *error, gpointer data) {
    (void)provider;
    char *where = gtk_css_section_to_string(section);
    /* Developer-facing: a stylesheet that fails to parse is a bug in the views or the host, never the person's. */
    g_warning("Shenzhen Friends %s stylesheet: %s: %s", (const char *)data, where, error->message);
    g_free(where);
}

static GtkCssProvider *add_provider(GdkDisplay *display, guint priority, const char *what) {
    GtkCssProvider *provider = gtk_css_provider_new();
    g_signal_connect(provider, "parsing-error", G_CALLBACK(log_css_error), (gpointer)what);
    g_object_bind_property_full(adw_style_manager_get_for_display(display), "dark", provider, "prefers-color-scheme",
                                G_BINDING_SYNC_CREATE, dark_to_scheme, NULL, NULL, NULL);
    gtk_style_context_add_provider_for_display(display, GTK_STYLE_PROVIDER(provider), priority);
    return provider;
}

void szfriends_gtk_style_ensure(GdkDisplay *display, const SZFriendsGtkHost *host) {
    if (!display || g_object_get_data(G_OBJECT(display), "szfriends-style")) return;
    szfriends_gtk_resource();
    gtk_icon_theme_add_resource_path(gtk_icon_theme_get_for_display(display), SZFRIENDS_GTK_RESOURCE_PREFIX "/icons");
    GtkCssProvider *views = add_provider(display, GTK_STYLE_PROVIDER_PRIORITY_APPLICATION, "views");
    gtk_css_provider_load_from_resource(views, SZFRIENDS_GTK_RESOURCE_PREFIX "/szfriends_gtk.css");
    /* The host's tokens come after ours and win: a named colour resolves from the highest-priority provider. */
    GtkCssProvider *custom = NULL;
    if (host && host->appearance_css && *host->appearance_css) {
        custom = add_provider(display, GTK_STYLE_PROVIDER_PRIORITY_APPLICATION + 1, "host");
        gtk_css_provider_load_from_string(custom, host->appearance_css);
    }
    GPtrArray *providers = g_ptr_array_new_with_free_func(g_object_unref);
    g_ptr_array_add(providers, views);
    if (custom) g_ptr_array_add(providers, custom);
    g_object_set_data_full(G_OBJECT(display), "szfriends-style", providers, (GDestroyNotify)g_ptr_array_unref);
}
